package main

import (
    "fmt"
    "sort"
    "time"
)

// O(n²) 冒泡排序 vs O(n log n) 标准库排序
func bubbleSort(arr []int) {
    n := len(arr)
    for i := 0; i < n-1; i++ {
        for j := 0; j < n-i-1; j++ {
            if arr[j] > arr[j+1] {
                arr[j], arr[j+1] = arr[j+1], arr[j]
            }
        }
    }
}

func benchmark(n int) {
    data1 := make([]int, n)
    data2 := make([]int, n)
    for i := range data1 {
        data1[i] = n - i
        data2[i] = n - i
    }

    t1 := time.Now()
    if n <= 10000 {
        bubbleSort(data1)
    }
    d1 := time.Since(t1)

    t2 := time.Now()
    sort.Ints(data2)
    d2 := time.Since(t2)

    if n <= 10000 {
        fmt.Printf("n=%6d: 冒泡=%v 快排=%v 比值=%.0fx\n",
            n, d1, d2, float64(d1)/float64(d2))
    } else {
        fmt.Printf("n=%6d: 快排=%v（冒泡跳过，太慢）\n", n, d2)
    }
}

func main() {
    for _, n := range []int{1000, 5000, 10000, 100000, 1000000} {
        benchmark(n)
    }
}

package main

import "fmt"

// 手动实现动态数组，观察扩容时机
type DynArray struct {
    data     []int
    size     int
    copyOps  int  // 记录总复制操作数
}

func (d *DynArray) Append(v int) {
    if d.size == len(d.data) {
        // 扩容：容量翻倍
        newData := make([]int, max(1, len(d.data)*2))
        copy(newData, d.data)
        d.copyOps += d.size  // 记录这次扩容的代价
        d.data = newData
    }
    d.data[d.size] = v
    d.size++
}

func max(a, b int) int {
    if a > b { return a }
    return b
}

func main() {
    d := &DynArray{}
    n := 1024
    for i := 0; i < n; i++ {
        d.Append(i)
    }
    fmt.Printf("追加 %d 次，总复制操作: %d，均摊: %.1f 次/追加\n",
        n, d.copyOps, float64(d.copyOps)/float64(n))
    // 追加 1024 次，总复制操作: 1023，均摊: ~1.0 次/追加
}
